 L.marker(network.nodes[trip.node],{zIndexOffset:1000,icon:L.divIcon({className:'practice-unit',html:`<span style="transform:rotate(${trip.heading}deg)">▲</span>`,iconSize:[16,16],iconAnchor:[8,8]})}).addTo(tripLayer);
