 $('.practice-stats').innerHTML=`<div><strong>${miles(trip?.meters||0)}</strong><span>Driven</span></div><div><strong>${trip?.history.filter(h=>h.turn!=='Continue').length||0}</strong><span>Turns / departures</span></div>`;
 $('#practice-review').disabled=!active;$('#practice-review').textContent=review?'Resume practice':'Pause & review route';$('#practice-return').hidden=!(trip?.status==='arrived'&&trip.leg==='outbound');$('#practice-restart').hidden=!trip;
